}

testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { montarRespostaHttp } from './solution.mjs';

test('GET: 200 com os dados em JSON', () => {
  const resposta = montarRespostaHttp({ method: 'GET', url: '/api/ola' }, { mensagem: 'olá' });
  assert.deepEqual(resposta, { statusCode: 200, contentType: 'application/json', body: '{"mensagem":"olá"}' });
});

test('limite: objeto vazio vira {}', () => {
  const resposta = montarRespostaHttp({ method: 'GET', url: '/api/vazio' }, {});
  assert.equal(resposta.statusCode, 200);
  assert.equal(resposta.body, '{}');
});

test('método não permitido: 405 com erro em JSON', () => {
  const resposta = montarRespostaHttp({ method: 'PUT', url: '/api/ola' }, { mensagem: 'olá' });
  assert.deepEqual(resposta, { statusCode: 405, contentType: 'application/json', body: '{"erro":"método não permitido"}' });
});

test('request inválido: lança erro', () => {
  assert.throws(() => montarRespostaHttp(null, {}), /request inválido/);
});

solutionCode:
export function montarRespostaHttp(req, dados) {
  if (typeof req !== 'object' || req === null) {
    throw new Error('request inválido');
  }

  if (req.method !== 'GET') {
    return {
      statusCode: 405,
      contentType: 'application/json',
      body: JSON.stringify({ erro: 'método não permitido' }),
    };
  }

  return {
    statusCode: 200,
    contentType: 'application/json',
    body: JSON.stringify(dados),
  };
}
